            Add("NN-MEET-1", "Pip", "You're real! You're actually real! Oh, I hope the trip wasn't terrible.");
            Add("NN-MEET-2", "Pip", "I'm so sorry, I'm babbling. I've been practicing what to say for days.");
            Add("NN-MEET-3", "Pip", "Sit. Have a biscuit. I know, biscuits aren't tactics. They help.");
            Add("NN-MEET-4", "Pip", "I'm not the leader, by the way. I mostly keep the books and make tea.");
            Add("NN-TIP-WIND", "Pip", "Every toy winds up before it hits. Look for the bar over its head. It's not a trick. It's a courtesy.");
            Add("NN-TIP-BLOCK", "Pip", "Hold up your weapon and you'll raise a guard. It won't stop everything. Nothing does.");
            Add("NN-TIP-PERFECT", "Pip", "If you block *just* before the hit lands, it's a perfect block. The toy's thrown off balance. It feels wonderful, I'm told.");
            Add("NN-TIP-ROLL", "Pip", "If a hit's already coming, rolling is often quicker than arguing with it.");
            Add("NN-TIP-NOISE", "Pip", "Running is loud. Walking is quiet. If you need to be quiet, walk. It's very annoying, but it works.");
            Add("NN-TIP-PILES", "Pip", "Scrap piles refill. Search them, leave, come back. It's the only thing that fills up around here.");
            Add("NN-TIP-BATT", "Pip", "Batteries aren't for everything. Keep a few for the gadgets. Keep a few for yourself.");
            Add("NN-TIP-ARMOUR", "Pip", "Armor doesn't make you tough. It makes you a little less sorry afterwards.");
            Add("NN-TIP-BAG", "Pip", "Boss parts make a bigger backpack. It's a strange thing to be proud of, but I am.");
            Add("NN-TIP-LIGHT", "Pip", "Your flashlight helps you see. It helps them see you, too. I still use mine.");
            Add("NN-TIP-FRIENDS", "Pip", "If you're travelling, company helps. Even nervous company.");
            Add("NN-IDLE-1", "Pip", "I should really tidy these pages.");
            Add("NN-IDLE-2", "Pip", "Have you eaten? You look like you haven't eaten.");
            Add("NN-IDLE-3", "Pip", "There's a lot of sand in a library. I've given up.");
            Add("NN-IDLE-4", "Pip", "I'm on chapter nine. It's not going well. It never goes well. It goes in the end.");
            Add("NN-IDLE-5", "Pip", "If you see a pencil, tell me. They go missing here.");
            Add("NN-IDLE-6", "Pip", "I read all the Recall Notices. Then I read them again. Then I put them in a drawer.");
            Add("NN-IDLE-7", "Pip", "I wonder about the towns. What they sound like at night.");
            Add("NN-HAPPY-1", "Pip", "That was brilliant. I mean it.");
            Add("NN-HAPPY-3", "Pip", "Oh, good. Oh, *good*.");
            Add("NN-HAPPY-4", "Pip", "I hoped you could. Very loudly.");
            Add("NN-SCARED-1", "Pip", "Oh. Oh no. Okay. Okay. Deep breaths. Mine too.");
            Add("NN-SCARED-2", "Pip", "Don't mind me. I'll just be over here, being very quiet.");
            Add("NN-SCARED-3", "Pip", "That sound. I know that sound. That's the Tape.");
            Add("NN-SCARED-4", "Pip", "If anything happens, the books are in the third car.");
            Add("NN-HUMBLE-1", "Pip", "I'm not much of a fighter. I just know a few things.");
            Add("NN-HUMBLE-2", "Pip", "I'd never lead anyone. I'm happy to carry the bags, though.");
            Add("NN-HUMBLE-3", "Pip", "I'm only the one writing things down. You're the ones out there doing them.");
            Add("NN-REACT-BOSS", "Pip", "A Mama-class unit. You beat a Mama-class unit. I'm going to sit down.");
            Add("NN-REACT-TAPE", "Pip", "Oh. It's warm. Is it supposed to be warm?");
            Add("NN-REACT-DOWN", "Pip", "You're all right. You're all right. Look, you're sitting up.");
            Add("NN-REACT-NOTICE", "Pip", "I've read that one. I've read all of them. They never get friendlier.");
            Add("NN-BYE-1", "Pip", "Be careful. Please be careful. And come back, I'll have more pages ready.");
            Add("NN-BYE-2", "Pip", "Take a biscuit. For the road. I know, it's a long road.");
            Add("NN-BYE-3", "Pip", "I'll leave the lights on.");
            Add("NN-BOOK-1", "Pip", "Chapter 3: When the siren sounds, don't run. Walk, quietly, toward the person who looks most afraid.");
            Add("NN-BOOK-2", "Pip", "Chapter 7: You are allowed to be scared. Being scared means you noticed something real.");
            Add("NN-BOOK-3", "Pip", "Chapter 11: A toy is only as dangerous as what it's been told. Be careful what you say to anything.");
            Add("NN-BOOK-4", "Pip", "Chapter 1: You can't help anyone if you don't sit down occasionally.");
            Add("NN-BOOK-5", "Pip", "Chapter 5: Write down what scared you. It gets smaller on the page.");
            Add("NN-BOOK-6", "Pip", "Chapter 8: If somebody asks for help, ask what they need before deciding you can't.");
            Add("NN-BOOK-7", "Pip", "Chapter 9: Being scared doesn't mean turn back. Sometimes it means check your batteries.");
            Add("NN-BOOK-8", "Pip", "Chapter 12: Don't be the hero. Be the one who brought the bandages.");
            Add("RAD-1", "Radio", "...this is Harbor, can anyone read me...");
            Add("RAD-2", "Radio", "...Lodge here. The snow's covering the Line. We can't get out...");
            Add("RAD-3", "Radio", "...Fairground. The lights are still on. That's the worst part...");
            Add("RAD-4", "Radio", "...we're out of bandages, we're out of batteries, we're not out of hope...");
            Add("RAD-5", "Radio", "...it's quiet tonight. That's worse...");
            Add("RAD-6", "Radio", "...if you're on the Line, get off at the next stop...");
            Add("RAD-7", "Radio", "...Hollow. Fog. Something's singing in the fog...");
            Add("RAD-8", "Radio", "...tell the library car we got the pages. Thank you. Tell Pip thank you...");
            Add("RAD-9", "Radio", "...is anyone still out there? We're still here...");
            Add("RAD-10", "Radio", "...do not play the Tape in the dark...");
        }
    }
}
